import React, { useState } from 'react';
import Modal from './Modal';
import { popularDadosTeste } from '../../utils/constants';
import { atualizarDadosSINAPI } from '../../utils/sinapi';

function MenuModal({ isOpen, onClose, onAbrirCatalogo, onAbrirItens, onAbrirConfig, onAbrirIA }) {
  const [atualizandoSINAPI, setAtualizandoSINAPI] = useState(false);

  const handleAtualizarSINAPI = async () => {
    if (!window.confirm('🔄 Atualizar dados do SINAPI?\n\nIsso carregará os dados mais recentes do arquivo JSON.\n\nContinuar?')) {
      return;
    }

    setAtualizandoSINAPI(true);

    try {
      const sucesso = await atualizarDadosSINAPI();
      
      if (sucesso) {
        alert('✅ SINAPI atualizado com sucesso!\n\nOs novos dados já estão disponíveis.');
        onClose();
      } else {
        alert('⚠️ Não foi possível atualizar.\n\nVerifique se o arquivo sinapi.json está em public/ e tente novamente.\n\nUsando dados estáticos.');
      }
    } catch (error) {
      console.error('Erro ao atualizar SINAPI:', error);
      alert('❌ Erro ao atualizar dados.\n\nVerifique o console para mais detalhes.');
    } finally {
      setAtualizandoSINAPI(false);
    }
  };
  
  const handleExportar = () => {
    const data = {
      clientes: localStorage.getItem('oc_cli') || '{}',
      orcamentos: localStorage.getItem('oc_orc') || '{}',
      pagamentos: localStorage.getItem('oc_pag') || '[]',
      agenda: localStorage.getItem('oc_agenda') || '[]',
      custos: localStorage.getItem('oc_custos') || '[]'
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `mestre-ia-backup-${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const popularClientesComEnderecos = () => {
    if (!window.confirm('🏠 Popular com clientes e pedidos de teste?\n\n✅ 20 clientes com endereços reais\n✅ Pedidos com serviços SINAPI reais\n✅ Materiais calculados automaticamente\n✅ Fotos e dados completos')) {
      return;
    }

    const resultado = popularDadosTeste();
    
    alert(`✅ Dados populados com sucesso!\n\n👥 ${resultado.totalClientes} clientes\n📋 ${resultado.totalPedidos} pedidos\n🔨 Serviços com dados do SINAPI 2026-04\n\nRecarregando...`);
    window.location.reload();
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} titulo="⚙️ Menu">
      <div className="modal-row">
        <button className="modal-btn" onClick={onAbrirItens}>
          📝 Editar Itens
        </button>
        <button className="modal-btn" onClick={onAbrirCatalogo}>
          📚 Catálogo
        </button>
      </div>
      
      <div className="modal-row">
        <button className="modal-btn" onClick={onAbrirConfig}>
          🎨 Aparência
        </button>
        <button className="modal-btn" onClick={onAbrirIA}>
          🤖 Configurar IA
        </button>
        <button className="modal-btn" onClick={handleExportar}>
          💾 Exportar
        </button>
      </div>

      <div className="modal-row">
        <button 
          className="modal-btn" 
          onClick={handleAtualizarSINAPI}
          disabled={atualizandoSINAPI}
          style={{ 
            background: atualizandoSINAPI ? '#6c757d' : '#007bff',
            cursor: atualizandoSINAPI ? 'not-allowed' : 'pointer',
            opacity: atualizandoSINAPI ? 0.7 : 1
          }}
        >
          {atualizandoSINAPI ? '⏳ Atualizando...' : '🔄 Atualizar SINAPI'}
        </button>
        <button className="modal-btn" onClick={popularClientesComEnderecos} style={{ background: '#4CAF50' }}>
          🏠 Popular Clientes
        </button>
        <button className="modal-btn" onClick={() => {
          if (window.confirm('Deseja limpar apenas clientes inválidos?')) {
            // Limpa apenas clientes inválidos
            const cli = JSON.parse(localStorage.getItem('oc_cli') || '{}');
            const clientesValidos = {};
            Object.keys(cli).forEach(key => {
              if (cli[key].nome && cli[key].nome.trim() !== '') {
                clientesValidos[key] = cli[key];
              }
            });
            localStorage.setItem('oc_cli', JSON.stringify(clientesValidos));
            window.location.reload();
          }
        }}>
          🧹 Limpar Inválidos
        </button>
        <button className="modal-btn" onClick={() => {
          if (window.confirm('Deseja realmente limpar todos os dados?')) {
            localStorage.clear();
            window.location.reload();
          }
        }}>
          🗑️ Limpar Tudo
        </button>
      </div>
      
      <button className="modal-close" onClick={onClose}>Fechar</button>
    </Modal>
  );
}

export default MenuModal;
