import React, { useState, useEffect } from 'react';
import Modal from './Modal';
import './MaterialModal.css';
import { uid } from '../../utils/helpers';
import { obterMateriaisDoServico, obterMateriaisPorCategorias } from '../../utils/sinapi';

function AdicionarMaterialModal({ isOpen, onClose, onSalvar, servicosSelecionados = [], materiaisJaAdicionados = [] }) {
  const [abaAtiva, setAbaAtiva] = useState('novo'); // 'novo' ou 'sinapi'
  const [formData, setFormData] = useState({
    nome: '',
    valorUnitario: '',
    quantidade: '1',
    unidade: 'un'
  });
  
  // Materiais do SINAPI baseados nos serviços
  const [materiaisSINAPI, setMateriaisSINAPI] = useState([]);
  const [materiaisSelecionados, setMateriaisSelecionados] = useState([]);
  const [buscaMaterial, setBuscaMaterial] = useState('');

  useEffect(() => {
    const carregarMateriais = async () => {
      if (isOpen && servicosSelecionados.length > 0) {
        // Extrai categorias únicas dos serviços SINAPI selecionados
        const categorias = [...new Set(
          servicosSelecionados
            .filter(s => s.origem === 'SINAPI' && s.categoria)
            .map(s => s.categoria)
        )];

        if (categorias.length > 0) {
          // Busca TODOS os materiais dessas categorias
          const todosMateriaisDaCategoria = await obterMateriaisPorCategorias(categorias);
          
          // Remove duplicatas por código
          const materiaisUnicos = Array.from(
            new Map(todosMateriaisDaCategoria.map(m => [m.codigo, m])).values()
          );

          setMateriaisSINAPI(materiaisUnicos);
          
          // Auto-seleciona materiais que já foram adicionados ao pedido
          const codigosJaAdicionados = materiaisJaAdicionados
            .filter(m => m.origem === 'SINAPI' && m.codigo)
            .map(m => m.codigo);
          
          const jaAdicionados = materiaisUnicos
            .filter(m => codigosJaAdicionados.includes(m.codigo))
            .map(m => ({
              ...m,
              quantidadeAjustada: materiaisJaAdicionados.find(ma => ma.codigo === m.codigo)?.quantidade || m.quantidade
            }));
          
          setMateriaisSelecionados(jaAdicionados);
        } else {
          setMateriaisSINAPI([]);
          setMateriaisSelecionados([]);
        }
      } else {
        setMateriaisSINAPI([]);
        setMateriaisSelecionados([]);
      }
    };
    
    carregarMateriais();
  }, [isOpen, servicosSelecionados, materiaisJaAdicionados]);

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const calcularTotal = () => {
    const valor = parseFloat(formData.valorUnitario) || 0;
    const qtd = parseFloat(formData.quantidade) || 0;
    return valor * qtd;
  };

  const handleSalvarNovo = () => {
    if (!formData.nome.trim()) {
      alert('Preencha o nome do material');
      return;
    }
    if (!formData.valorUnitario || parseFloat(formData.valorUnitario) <= 0) {
      alert('Informe um valor unitário válido');
      return;
    }
    if (!formData.quantidade || parseFloat(formData.quantidade) <= 0) {
      alert('Informe uma quantidade válida');
      return;
    }

    const material = {
      id: uid(),
      nome: formData.nome.trim(),
      valorUnitario: parseFloat(formData.valorUnitario),
      quantidade: parseFloat(formData.quantidade),
      unidadeMedida: formData.unidade,
      unidade: formData.unidade,
      total: calcularTotal(),
      origem: 'manual'
    };

    onSalvar(material);
    
    // Limpar formulário
    setFormData({
      nome: '',
      valorUnitario: '',
      quantidade: '1',
      unidade: 'un'
    });
    onClose();
  };

  const handleToggleMaterialSINAPI = (material) => {
    const jaSelecionado = materiaisSelecionados.find(m => m.codigo === material.codigo);
    
    if (jaSelecionado) {
      setMateriaisSelecionados(materiaisSelecionados.filter(m => m.codigo !== material.codigo));
    } else {
      setMateriaisSelecionados([...materiaisSelecionados, { ...material, quantidadeAjustada: material.quantidade }]);
    }
  };

  const atualizarQuantidadeMaterial = (codigo, novaQuantidade) => {
    setMateriaisSelecionados(materiaisSelecionados.map(m => 
      m.codigo === codigo 
        ? { ...m, quantidadeAjustada: parseFloat(novaQuantidade) || 0 }
        : m
    ));
  };

  const handleAdicionarMateriaisSINAPI = () => {
    if (materiaisSelecionados.length === 0) return;

    materiaisSelecionados.forEach(mat => {
      const material = {
        id: uid(),
        codigo: mat.codigo,
        nome: mat.nome,
        valorUnitario: mat.valorUnitario,
        quantidade: mat.quantidadeAjustada,
        unidadeMedida: mat.unidadeMedida,
        unidade: mat.unidadeMedida,
        total: mat.valorUnitario * mat.quantidadeAjustada,
        origem: 'SINAPI',
        codigoServico: mat.servicoOrigem
      };

      onSalvar(material);
    });

    setMateriaisSelecionados([]);
    onClose();
  };

  const formValido = 
    formData.nome.trim().length > 0 &&
    parseFloat(formData.valorUnitario) > 0 &&
    parseFloat(formData.quantidade) > 0;

  const total = calcularTotal();

  return (
    <Modal isOpen={isOpen} onClose={onClose} titulo="📦 Adicionar Material">
      <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        
        {/* Abas */}
        <div style={{ display: 'flex', gap: '8px', borderBottom: '2px solid var(--border)' }}>
          <button
            onClick={() => setAbaAtiva('novo')}
            style={{
              flex: 1,
              padding: '12px',
              background: abaAtiva === 'novo' ? 'var(--accent)' : 'transparent',
              border: 'none',
              borderBottom: abaAtiva === 'novo' ? '2px solid var(--accent)' : 'none',
              color: abaAtiva === 'novo' ? '#fff' : 'var(--text)',
              fontSize: '14px',
              fontWeight: '600',
              cursor: 'pointer',
              borderRadius: '8px 8px 0 0',
              marginBottom: '-2px'
            }}
          >
            🆕 Novo Material
          </button>
          <button
            onClick={() => setAbaAtiva('sinapi')}
            style={{
              flex: 1,
              padding: '12px',
              background: abaAtiva === 'sinapi' ? 'var(--accent)' : 'transparent',
              border: 'none',
              borderBottom: abaAtiva === 'sinapi' ? '2px solid var(--accent)' : 'none',
              color: abaAtiva === 'sinapi' ? '#fff' : 'var(--text)',
              fontSize: '14px',
              fontWeight: '600',
              cursor: 'pointer',
              borderRadius: '8px 8px 0 0',
              marginBottom: '-2px'
            }}
          >
            📊 Tabela SINAPI
            {materiaisSINAPI.length > 0 && ` (${materiaisSINAPI.length})`}
          </button>
        </div>

        {/* ABA NOVO MATERIAL */}
        {abaAtiva === 'novo' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {/* Nome */}
            <div>
              <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', fontSize: '13px', color: 'var(--muted)' }}>
                Nome do material <span style={{ color: 'red' }}>*</span>
              </label>
              <input
                type="text"
                value={formData.nome}
                onChange={(e) => handleChange('nome', e.target.value)}
                placeholder="Ex: Cimento, Areia, Tinta..."
                style={{
                  width: '100%',
                  padding: '12px',
                  background: 'var(--bg)',
                  border: '1px solid var(--border)',
                  borderRadius: '8px',
                  color: 'var(--text)',
                  fontSize: '14px'
                }}
              />
            </div>

            {/* Preço, Quantidade e Unidade */}
            <div style={{ display: 'grid', gridTemplateColumns: '2fr 2fr 1fr', gap: '12px' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', fontSize: '13px', color: 'var(--muted)' }}>
                  Preço unitário (R$) <span style={{ color: 'red' }}>*</span>
                </label>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={formData.valorUnitario}
                  onChange={(e) => handleChange('valorUnitario', e.target.value)}
                  placeholder="0,00"
                  style={{
                    width: '100%',
                    padding: '12px',
                    background: 'var(--bg)',
                    border: '1px solid var(--border)',
                    borderRadius: '8px',
                    color: 'var(--text)',
                    fontSize: '14px'
                  }}
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', fontSize: '13px', color: 'var(--muted)' }}>
                  Quantidade <span style={{ color: 'red' }}>*</span>
                </label>
                <input
                  type="number"
                  step="1"
                  min="1"
                  value={formData.quantidade}
                  onChange={(e) => handleChange('quantidade', e.target.value)}
                  placeholder="1"
                  style={{
                    width: '100%',
                    padding: '12px',
                    background: 'var(--bg)',
                    border: '1px solid var(--border)',
                    borderRadius: '8px',
                    color: 'var(--text)',
                    fontSize: '14px'
                  }}
                />
              </div>

              <div>
                <label style={{ display: 'block', marginBottom: '8px', fontWeight: '600', fontSize: '13px', color: 'var(--muted)' }}>
                  Un.
                </label>
                <select
                  value={formData.unidade}
                  onChange={(e) => handleChange('unidade', e.target.value)}
                  style={{
                    width: '100%',
                    padding: '12px',
                    background: 'var(--bg)',
                    border: '1px solid var(--border)',
                    borderRadius: '8px',
                    color: 'var(--text)',
                    fontSize: '14px',
                    cursor: 'pointer'
                  }}
                >
                  <option value="un">un</option>
                  <option value="kg">kg</option>
                  <option value="g">g</option>
                  <option value="L">L</option>
                  <option value="ml">ml</option>
                  <option value="m">m</option>
                  <option value="m²">m²</option>
                  <option value="m³">m³</option>
                  <option value="cx">cx</option>
                  <option value="pct">pct</option>
                  <option value="sc">sc</option>
                </select>
              </div>
            </div>

            {/* Preview do total */}
            <div style={{
              padding: '16px',
              background: 'var(--bg3)',
              borderRadius: '8px',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              border: '2px solid var(--accent)'
            }}>
              <span style={{ fontSize: '14px', fontWeight: '600', color: 'var(--muted)' }}>
                Valor total:
              </span>
              <strong style={{ fontSize: '20px', color: 'var(--accent)' }}>
                R$ {total.toFixed(2).replace('.', ',')}
              </strong>
            </div>

            {/* Botões */}
            <div style={{ display: 'flex', gap: '8px', marginTop: '8px' }}>
              <button
                onClick={onClose}
                style={{
                  flex: 1,
                  padding: '12px',
                  background: 'var(--bg3)',
                  border: '1px solid var(--border)',
                  borderRadius: '8px',
                  color: 'var(--text)',
                  fontSize: '14px',
                  fontWeight: '500',
                  cursor: 'pointer'
                }}
              >
                Cancelar
              </button>
              <button
                onClick={handleSalvarNovo}
                disabled={!formValido}
                style={{
                  flex: 1,
                  padding: '12px',
                  background: formValido ? 'var(--accent)' : 'var(--bg3)',
                  border: 'none',
                  borderRadius: '8px',
                  color: formValido ? '#fff' : 'var(--muted)',
                  fontSize: '14px',
                  fontWeight: '600',
                  cursor: formValido ? 'pointer' : 'not-allowed',
                  opacity: formValido ? 1 : 0.5
                }}
              >
                ✅ Salvar
              </button>
            </div>
          </div>
        )}

        {/* ABA SINAPI */}
        {abaAtiva === 'sinapi' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {materiaisSINAPI.length === 0 ? (
              <div style={{
                padding: '32px',
                textAlign: 'center',
                color: 'var(--muted)',
                background: 'var(--bg2)',
                borderRadius: '8px'
              }}>
                <div style={{ fontSize: '48px', marginBottom: '16px' }}>📦</div>
                <div style={{ fontSize: '14px' }}>
                  Nenhum material disponível
                </div>
                <div style={{ fontSize: '12px', marginTop: '8px' }}>
                  Selecione serviços do SINAPI primeiro para ver os materiais relacionados
                </div>
              </div>
            ) : (
              <>
                <div style={{ fontSize: '12px', color: 'var(--muted)', padding: '8px', background: 'var(--bg2)', borderRadius: '6px' }}>
                  💡 Sugestão: Todos os materiais relacionados às categorias dos serviços selecionados
                </div>

                {/* Campo de Busca */}
                <div style={{ position: 'relative' }}>
                  <input
                    type="text"
                    placeholder="🔍 Buscar material... (ex: tubo, cabo, tinta)"
                    value={buscaMaterial}
                    onChange={(e) => setBuscaMaterial(e.target.value)}
                    style={{
                      width: '100%',
                      padding: '12px 40px 12px 12px',
                      background: 'var(--bg)',
                      border: '2px solid var(--border)',
                      borderRadius: '8px',
                      color: 'var(--text)',
                      fontSize: '14px',
                      outline: 'none',
                      transition: 'border-color 0.2s'
                    }}
                    onFocus={(e) => e.target.style.borderColor = 'var(--accent)'}
                    onBlur={(e) => e.target.style.borderColor = 'var(--border)'}
                  />
                  {buscaMaterial && (
                    <button
                      onClick={() => setBuscaMaterial('')}
                      style={{
                        position: 'absolute',
                        right: '8px',
                        top: '50%',
                        transform: 'translateY(-50%)',
                        background: 'var(--bg3)',
                        border: 'none',
                        borderRadius: '50%',
                        width: '28px',
                        height: '28px',
                        cursor: 'pointer',
                        fontSize: '16px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: 'var(--text)'
                      }}
                    >
                      ✕
                    </button>
                  )}
                </div>

                {/* Contador de resultados */}
                {buscaMaterial && (
                  <div style={{ fontSize: '12px', color: 'var(--muted)', padding: '4px 8px' }}>
                    {materiaisSINAPI.filter(m => 
                      m.nome.toLowerCase().includes(buscaMaterial.toLowerCase()) ||
                      m.codigo.toLowerCase().includes(buscaMaterial.toLowerCase())
                    ).length} material(is) encontrado(s)
                  </div>
                )}

                {/* Lista de materiais */}
                <div style={{ maxHeight: '400px', overflowY: 'auto' }}>
                  {materiaisSINAPI
                    .filter(material => {
                      if (!buscaMaterial) return true;
                      const busca = buscaMaterial.toLowerCase();
                      return material.nome.toLowerCase().includes(busca) ||
                             material.codigo.toLowerCase().includes(busca) ||
                             material.categoriaServico.toLowerCase().includes(busca);
                    })
                    .map((material, index) => {
                    const selecionado = materiaisSelecionados.find(m => m.codigo === material.codigo);
                    const jaNoOrcamento = materiaisJaAdicionados.find(m => m.codigo === material.codigo);
                    
                    return (
                      <div
                        key={`${material.codigo}-${index}`}
                        onClick={() => handleToggleMaterialSINAPI(material)}
                        style={{
                          padding: '12px',
                          background: selecionado ? 'var(--accent-light)' : 'var(--bg2)',
                          border: `2px solid ${selecionado ? 'var(--accent)' : 'var(--border)'}`,
                          borderRadius: '8px',
                          marginBottom: '8px',
                          cursor: 'pointer',
                          transition: 'all 0.2s',
                          opacity: jaNoOrcamento && !selecionado ? 0.6 : 1
                        }}
                      >
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                          <div style={{ flex: 1 }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '4px' }}>
                              <span style={{ fontSize: '11px', color: 'var(--muted)' }}>
                                {material.categoriaServico}
                              </span>
                              {jaNoOrcamento && (
                                <span style={{ 
                                  fontSize: '10px', 
                                  backgroundColor: 'var(--accent)',
                                  color: '#fff',
                                  padding: '2px 6px',
                                  borderRadius: '4px',
                                  fontWeight: '600'
                                }}>
                                  ✓ Já no orçamento
                                </span>
                              )}
                            </div>
                            <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '6px' }}>
                              {material.nome}
                            </div>
                            <div style={{ fontSize: '12px', color: 'var(--muted)' }}>
                              R$ {material.valorUnitario.toFixed(2)} / {material.unidadeMedida}
                              {jaNoOrcamento && (
                                <span style={{ marginLeft: '8px', fontWeight: '600', color: 'var(--accent)' }}>
                                  • Qtd: {jaNoOrcamento.quantidade} {jaNoOrcamento.unidadeMedida}
                                </span>
                              )}
                            </div>

                            {/* Campo de quantidade se selecionado */}
                            {selecionado && (
                              <div style={{ marginTop: '10px' }} onClick={(e) => e.stopPropagation()}>
                                <label style={{ fontSize: '11px', color: 'var(--muted)', display: 'block', marginBottom: '4px' }}>
                                  Quantidade ({material.unidadeMedida}):
                                </label>
                                <input
                                  type="number"
                                  value={selecionado.quantidadeAjustada}
                                  onChange={(e) => atualizarQuantidadeMaterial(material.codigo, e.target.value)}
                                  step="1"
                                  min="1"
                                  style={{
                                    width: '100%',
                                    padding: '8px',
                                    background: 'var(--bg)',
                                    border: '1px solid var(--border)',
                                    borderRadius: '6px',
                                    color: 'var(--text)',
                                    fontSize: '13px'
                                  }}
                                />
                                <div style={{ marginTop: '6px', fontSize: '12px', fontWeight: '600', color: 'var(--accent)' }}>
                                  Total: R$ {(material.valorUnitario * selecionado.quantidadeAjustada).toFixed(2)}
                                </div>
                              </div>
                            )}
                          </div>

                          <div style={{
                            width: '24px',
                            height: '24px',
                            background: selecionado ? 'var(--accent)' : 'var(--bg3)',
                            border: `2px solid ${selecionado ? 'var(--accent)' : 'var(--border)'}`,
                            borderRadius: '4px',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            color: '#fff',
                            fontSize: '14px',
                            fontWeight: 'bold',
                            flexShrink: 0,
                            marginLeft: '10px'
                          }}>
                            {selecionado && '✓'}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                  
                  {/* Mensagem quando não encontra resultados na busca */}
                  {buscaMaterial && materiaisSINAPI.filter(m => 
                    m.nome.toLowerCase().includes(buscaMaterial.toLowerCase()) ||
                    m.codigo.toLowerCase().includes(buscaMaterial.toLowerCase()) ||
                    m.categoriaServico.toLowerCase().includes(buscaMaterial.toLowerCase())
                  ).length === 0 && (
                    <div style={{
                      padding: '32px',
                      textAlign: 'center',
                      color: 'var(--muted)',
                      background: 'var(--bg2)',
                      borderRadius: '8px'
                    }}>
                      <div style={{ fontSize: '32px', marginBottom: '12px' }}>🔍</div>
                      <div style={{ fontSize: '14px', fontWeight: '600', marginBottom: '8px' }}>
                        Nenhum material encontrado
                      </div>
                      <div style={{ fontSize: '12px' }}>
                        Tente buscar por outro termo ou limpe o filtro
                      </div>
                    </div>
                  )}
                </div>

                {/* Painel de resumo e ação */}
                {materiaisSelecionados.length > 0 && (
                  <div style={{
                    padding: '12px',
                    background: 'var(--bg3)',
                    borderRadius: '8px',
                    border: '2px solid var(--accent)'
                  }}>
                    <div style={{ fontSize: '14px', fontWeight: '600', marginBottom: '8px' }}>
                      {materiaisSelecionados.length} material(is) selecionado(s)
                    </div>
                    <div style={{ fontSize: '16px', fontWeight: '700', color: 'var(--accent)' }}>
                      Total: R$ {materiaisSelecionados.reduce((sum, m) => 
                        sum + (m.valorUnitario * m.quantidadeAjustada), 0
                      ).toFixed(2)}
                    </div>
                  </div>
                )}

                {/* Botões */}
                <div style={{ display: 'flex', gap: '8px' }}>
                  <button
                    onClick={onClose}
                    style={{
                      flex: 1,
                      padding: '12px',
                      background: 'var(--bg3)',
                      border: '1px solid var(--border)',
                      borderRadius: '8px',
                      color: 'var(--text)',
                      fontSize: '14px',
                      fontWeight: '500',
                      cursor: 'pointer'
                    }}
                  >
                    Cancelar
                  </button>
                  <button
                    onClick={handleAdicionarMateriaisSINAPI}
                    disabled={materiaisSelecionados.length === 0}
                    style={{
                      flex: 2,
                      padding: '12px',
                      background: materiaisSelecionados.length > 0 ? 'var(--accent)' : 'var(--bg3)',
                      border: 'none',
                      borderRadius: '8px',
                      color: materiaisSelecionados.length > 0 ? '#fff' : 'var(--muted)',
                      fontSize: '14px',
                      fontWeight: '600',
                      cursor: materiaisSelecionados.length > 0 ? 'pointer' : 'not-allowed',
                      opacity: materiaisSelecionados.length > 0 ? 1 : 0.5
                    }}
                  >
                    ✅ Adicionar {materiaisSelecionados.length > 0 ? `${materiaisSelecionados.length} Material(is)` : 'Materiais'}
                  </button>
                </div>
              </>
            )}
          </div>
        )}
      </div>
    </Modal>
  );
}

export default AdicionarMaterialModal;
