import React, { useState, useEffect } from 'react';
import Modal from './Modal';
import './ServicoModal.css';

function RevisarPedidoModal({ isOpen, onClose, servicos, onSalvarServicos }) {
  const [servicosEditados, setServicosEditados] = useState([]);

  useEffect(() => {
    if (isOpen && servicos) {
      // Cria cópia dos serviços para edição
      setServicosEditados(servicos.map(s => ({ ...s })));
    }
  }, [isOpen, servicos]);

  const atualizarQuantidade = (index, valor) => {
    const novosServicos = [...servicosEditados];
    novosServicos[index].quantidade = parseFloat(valor) || 1;
    setServicosEditados(novosServicos);
  };

  const atualizarValor = (index, valor) => {
    const novosServicos = [...servicosEditados];
    novosServicos[index].valorUnitario = parseFloat(valor) || 0;
    setServicosEditados(novosServicos);
  };

  const removerServico = (index) => {
    const novosServicos = servicosEditados.filter((_, i) => i !== index);
    setServicosEditados(novosServicos);
  };

  const handleSalvar = () => {
    if (servicosEditados.length === 0) {
      alert('⚠️ Adicione pelo menos um serviço');
      return;
    }
    onSalvarServicos(servicosEditados);
    onClose();
  };

  const calcularTotal = (servico) => {
    return (servico.valorUnitario * servico.quantidade).toFixed(2);
  };

  const calcularTotalGeral = () => {
    return servicosEditados.reduce((total, s) => {
      return total + (s.valorUnitario * s.quantidade);
    }, 0).toFixed(2);
  };

  return (
    <Modal isOpen={isOpen} onClose={onClose} titulo="📋 Revisar Serviços">
      <div style={{ maxHeight: '60vh', overflowY: 'auto', padding: '10px' }}>
        {servicosEditados.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '20px', color: 'var(--muted)' }}>
            Nenhum serviço selecionado
          </div>
        ) : (
          servicosEditados.map((servico, index) => (
            <div
              key={index}
              style={{
                border: '2px solid var(--border)',
                borderRadius: '8px',
                padding: '15px',
                marginBottom: '15px',
                backgroundColor: 'var(--bg2)'
              }}
            >
              {/* Cabeçalho com código e botão remover */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                <div>
                  {servico.codigoSINAPI && (
                    <span style={{ 
                      fontSize: '12px', 
                      color: 'var(--accent)',
                      fontWeight: 'bold',
                      backgroundColor: 'var(--accent-light)',
                      padding: '3px 8px',
                      borderRadius: '4px'
                    }}>
                      {servico.codigoSINAPI}
                    </span>
                  )}
                  {servico.categoria && (
                    <span style={{ 
                      fontSize: '12px', 
                      color: 'var(--muted)',
                      marginLeft: '8px',
                      backgroundColor: 'var(--bg3)',
                      padding: '3px 8px',
                      borderRadius: '4px'
                    }}>
                      {servico.categoria}
                    </span>
                  )}
                </div>
                <button
                  onClick={() => removerServico(index)}
                  style={{
                    background: '#dc3545',
                    color: 'white',
                    border: 'none',
                    borderRadius: '6px',
                    padding: '6px 12px',
                    cursor: 'pointer',
                    fontSize: '12px',
                    fontWeight: '600'
                  }}
                >
                  🗑️ Remover
                </button>
              </div>

              {/* Nome/Descrição do serviço */}
              <div style={{ marginBottom: '12px' }}>
                <strong style={{ fontSize: '14px', color: 'var(--text)', lineHeight: '1.4' }}>
                  {servico.nome}
                </strong>
              </div>

              {/* Campos de edição */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '10px' }}>
                {/* Quantidade */}
                <div>
                  <label style={{ fontSize: '12px', color: 'var(--muted)', display: 'block', marginBottom: '5px', fontWeight: '600' }}>
                    Quantidade ({servico.unidadeMedida || 'un'})
                  </label>
                  <input
                    type="number"
                    value={servico.quantidade}
                    onChange={(e) => atualizarQuantidade(index, e.target.value)}
                    min="1"
                    step="1"
                    style={{
                      width: '100%',
                      padding: '8px',
                      background: 'var(--bg)',
                      border: '1px solid var(--border)',
                      borderRadius: '6px',
                      color: 'var(--text)',
                      fontSize: '14px'
                    }}
                  />
                </div>

                {/* Valor Unitário */}
                <div>
                  <label style={{ fontSize: '12px', color: 'var(--muted)', display: 'block', marginBottom: '5px', fontWeight: '600' }}>
                    Valor Unit. (R$)
                  </label>
                  <input
                    type="number"
                    value={servico.valorUnitario}
                    onChange={(e) => atualizarValor(index, e.target.value)}
                    min="0"
                    step="0.01"
                    style={{
                      width: '100%',
                      padding: '8px',
                      background: 'var(--bg)',
                      border: '1px solid var(--border)',
                      borderRadius: '6px',
                      color: 'var(--text)',
                      fontSize: '14px'
                    }}
                  />
                </div>

                {/* Total */}
                <div>
                  <label style={{ fontSize: '12px', color: 'var(--muted)', display: 'block', marginBottom: '5px', fontWeight: '600' }}>
                    Total
                  </label>
                  <div style={{
                    padding: '8px',
                    backgroundColor: 'var(--accent-light)',
                    borderRadius: '6px',
                    fontSize: '14px',
                    fontWeight: 'bold',
                    color: 'var(--accent)',
                    textAlign: 'right',
                    border: '1px solid var(--accent)'
                  }}>
                    R$ {calcularTotal(servico)}
                  </div>
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Total Geral */}
      {servicosEditados.length > 0 && (
        <div style={{
          marginTop: '20px',
          padding: '15px',
          backgroundColor: 'var(--bg3)',
          borderRadius: '8px',
          border: '2px solid var(--accent)',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center'
        }}>
          <strong style={{ fontSize: '16px', color: 'var(--text)' }}>Total dos Serviços:</strong>
          <strong style={{ fontSize: '20px', color: 'var(--accent)' }}>R$ {calcularTotalGeral()}</strong>
        </div>
      )}

      {/* Botões */}
      <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
        <button
          onClick={onClose}
          style={{
            flex: 1,
            padding: '12px',
            background: 'var(--bg3)',
            border: '1px solid var(--border)',
            borderRadius: '8px',
            color: 'var(--text)',
            fontSize: '14px',
            fontWeight: '500',
            cursor: 'pointer'
          }}
        >
          Cancelar
        </button>
        <button
          onClick={handleSalvar}
          disabled={servicosEditados.length === 0}
          style={{
            flex: 2,
            background: servicosEditados.length > 0 ? 'var(--accent)' : 'var(--bg3)',
            color: servicosEditados.length > 0 ? '#fff' : 'var(--muted)',
            border: 'none',
            padding: '12px',
            borderRadius: '8px',
            cursor: servicosEditados.length > 0 ? 'pointer' : 'not-allowed',
            fontSize: '16px',
            fontWeight: 'bold',
            opacity: servicosEditados.length > 0 ? 1 : 0.5
          }}
        >
          ✅ Salvar e Voltar
        </button>
      </div>
    </Modal>
  );
}

export default RevisarPedidoModal;
