// Função para buscar serviço por código
export const buscarServicoPorCodigo = (codigo) => {
  return servicosSINAPI[codigo] || null;
};

// Função para buscar serviços por categoria
export const buscarServicosPorCategoria = (categoria) => {
  if (categoria === 'Todas') {
    return Object.values(servicosSINAPI);
  }
  return Object.values(servicosSINAPI).filter(s => s.categoria === categoria);
};

// Função para buscar serviços por texto
export const buscarServicos = (texto) => {
  const textoLower = texto.toLowerCase();
  return Object.values(servicosSINAPI).filter(s => 
    s.codigo.toLowerCase().includes(textoLower) ||
    s.descricao.toLowerCase().includes(textoLower) ||
    s.categoria.toLowerCase().includes(textoLower)
  );
};

// Função para calcular custo total de insumos
export const calcularCustoInsumos = (servico, quantidade = 1) => {
  if (!servico || !servico.insumos) return 0;
  
  return servico.insumos.reduce((total, insumo) => {
    return total + (insumo.precoUnitario * insumo.coeficiente * quantidade);
  }, 0);
};

// Cache de insumos carregados do JSON
let insumosCache = null;

// Função para carregar insumos do JSON (async)
const carregarInsumosDoJSON = async () => {
  if (insumosCache) return insumosCache;
  
  try {
    const response = await fetch('/sinapi.json');
    const data = await response.json();
    insumosCache = data.insumos || {};
    console.log('✅ Insumos carregados do JSON:', Object.keys(insumosCache).length);
    return insumosCache;
  } catch (error) {
    console.error('❌ Erro ao carregar sinapi.json:', error);
    return {};
  }
};

// Função para buscar insumos reais por palavras-chave
const buscarInsumosReais = async (palavrasChave, palavrasExcluir = [], limite = 3) => {
  const insumos = await carregarInsumosDoJSON();
  if (!insumos || Object.keys(insumos).length === 0) return [];
  
  const insumosArray = Object.values(insumos);
  const resultados = [];
  
  // Filtrar apenas MATERIAIS (excluir mão de obra, equipamentos, encargos)
  const maoDeObraKeywords = [
    'pedreiro', 'servente', 'ajudante', 'marceneiro', 'pintor',
    'eletricista', 'encanador', 'mestre', 'auxiliar', 'operador',
    'armador', 'carpinteiro', 'oficial', 'horista', 'mensalista',
    'montador', 'instalador', 'soldador', 'azulejista', 'gesseiro'
  ];
  
  const equipamentoKeywords = [
    'betoneira', 'equipamento', 'caminhão', 'trator', 'retroescavadeira',
    'compactador', 'vibrador', 'martelete', 'andaime', 'elevador'
  ];
  
  for (const insumo of insumosArray) {
    if (resultados.length >= limite) break;
    
    const desc = insumo.descricao?.toLowerCase() || '';
    const unidade = insumo.unidade?.toUpperCase() || '';
    
    // Pular mão de obra (unidade H = hora)
    if (unidade === 'H' || unidade === 'HORA' || unidade === 'MES') continue;
    
    // Pular se tem palavra-chave de mão de obra ou equipamento
    const temMaoDeObra = maoDeObraKeywords.some(k => desc.includes(k));
    const temEquipamento = equipamentoKeywords.some(k => desc.includes(k));
    if (temMaoDeObra || temEquipamento) continue;
    
    // Pular encargos
    if (desc.includes('encargo') || desc.includes('bdi')) continue;
    
    // Pular se contém palavras a excluir (contexto errado)
    const temPalavraExcluir = palavrasExcluir.some(palavra => desc.includes(palavra.toLowerCase()));
    if (temPalavraExcluir) continue;
    
    // Verificar se contém alguma palavra-chave
    const temPalavraChave = palavrasChave.some(palavra => desc.includes(palavra.toLowerCase()));
    if (temPalavraChave) {
      resultados.push({
        codigo: insumo.codigo,
        descricao: insumo.descricao,
        unidade: insumo.unidade,
        coeficiente: 1.0, // Coeficiente padrão
        precoUnitario: insumo.custoUnitarioSP || insumo.precoUnitario || 0
      });
    }
  }
  
  return resultados;
};

