// Função para obter materiais de um serviço (excluindo mão de obra)
export const obterMateriaisDoServico = async (servico, quantidadeServico = 1) => {
  if (!servico) return [];
  
  // IMPORTANTE: Os insumos hardcoded no arquivo estão incorretos/aleatórios
  // Por isso, sempre gera materiais inteligentes baseados na categoria do serviço
  const materiaisFinais = await gerarInsumosPadrao(servico);
  
  // Função para arredondar quantidade de forma inteligente
  const arredondarQuantidade = (valor, unidade) => {
    // Para unidades pequenas (UN, KG, L, M, etc), trabalha com inteiros
    const unidadesInteiras = ['UN', 'UN.', 'PC', 'PÇ', 'CJ', 'JG', 'CX', 'SC', 'BD', 'GL'];
    const unidadeUpper = unidade.toUpperCase();
    
    if (valor < 0.1) {
      // Valores muito pequenos: arredonda para 1
      return 1;
    } else if (valor < 1) {
      // Valores menores que 1: arredonda para cima
      return 1;
    } else if (valor <= 2) {
      // Entre 1 e 2: mantém inteiro arredondado para cima
      return Math.ceil(valor);
    } else if (valor <= 10) {
      // Entre 2 e 10: arredonda para inteiro
      return Math.round(valor);
    } else if (valor <= 50) {
      // Entre 10 e 50: arredonda para múltiplo de 5
      return Math.ceil(valor / 5) * 5;
    } else if (valor <= 100) {
      // Entre 50 e 100: arredonda para múltiplo de 10
      return Math.ceil(valor / 10) * 10;
    } else {
      // Maior que 100: arredonda para múltiplo de 25
      return Math.ceil(valor / 25) * 25;
    }
  };
  
  return materiaisFinais.map(insumo => {
    const quantidadeCalculada = insumo.coeficiente * quantidadeServico;
    const quantidadeArredondada = arredondarQuantidade(quantidadeCalculada, insumo.unidade);
    
    return {
      codigo: insumo.codigo,
      nome: insumo.descricao,
      unidadeMedida: insumo.unidade,
      quantidade: quantidadeArredondada,
      valorUnitario: insumo.precoUnitario,
      valorTotal: parseFloat((insumo.precoUnitario * quantidadeArredondada).toFixed(2)),
      origem: 'SINAPI',
      codigoServico: servico.codigo
    };
  });
};

// Buscar todos os materiais de determinadas categorias
export const obterMateriaisPorCategorias = async (categorias = []) => {
  if (!categorias || categorias.length === 0) return [];
  
  const materiaisUnicos = new Map();
  
  // Percorre todos os serviços das categorias especificadas
  for (const servico of Object.values(servicosSINAPI)) {
    if (categorias.includes(servico.categoria) && servico.insumos) {
      const materiais = await obterMateriaisDoServico(servico, 1);
      
      // Adiciona apenas materiais únicos (por código)
      materiais.forEach(mat => {
        if (!materiaisUnicos.has(mat.codigo)) {
          materiaisUnicos.set(mat.codigo, {
            ...mat,
            categoriaServico: servico.categoria,
            servicoOrigem: servico.codigo
          });
        }
      });
    }
  }
  
  return Array.from(materiaisUnicos.values());
};

