// Cache dos dados carregados do JSON
let dadosJSONCache = null;
let ultimaAtualizacaoJSON = null;
const CACHE_DURACAO = 5 * 60 * 1000; // 5 minutos

// Função para carregar dados do JSON dinamicamente
export const carregarDadosJSON = async () => {
  try {
    // Verifica se tem cache válido
    if (dadosJSONCache && ultimaAtualizacaoJSON && 
        (Date.now() - ultimaAtualizacaoJSON < CACHE_DURACAO)) {
      return dadosJSONCache;
    }

    // Carrega o JSON
    const response = await fetch(`${process.env.PUBLIC_URL}/sinapi.json`);
    
    if (!response.ok) {
      console.warn('❌ Não foi possível carregar sinapi.json');
      return null;
    }

    const data = await response.json();
    
    // Atualiza o cache
    dadosJSONCache = data;
    ultimaAtualizacaoJSON = Date.now();
    
    console.log(`✅ SINAPI JSON carregado: ${Object.keys(data.composicoes || {}).length} composições`);
    
    return data;
  } catch (error) {
    console.error('❌ Erro ao carregar SINAPI JSON:', error);
    return null;
  }
};

// Função para atualizar os dados do SINAPI com base no JSON
export const atualizarDadosSINAPI = async () => {
  try {
    const jsonData = await carregarDadosJSON();
    
    if (!jsonData || !jsonData.composicoes) {
      console.warn('⚠️ Mantendo dados estáticos do SINAPI');
      return false;
    }

    // Mapear categorias
    const categoriasMap = {
      'Alvenaria': 'Alvenaria',
      'Revestimento': 'Revestimento',
      'Pintura': 'Pintura',
      'Contrapiso': 'Contrapiso',
      'Impermeabilização': 'Impermeabilização',
      'Esquadrias': 'Esquadrias',
      'Forro': 'Forro',
      'Estrutura': 'Estrutura',
      'Instalações': 'Instalações Elétricas e Hidráulicas',
      'Cobertura': 'Cobertura',
      'Fundação': 'Fundação',
      'Geral': 'Geral'
    };

    let atualizados = 0;
    let novos = 0;

    // Atualizar serviços existentes e adicionar novos
    for (const [codigo, comp] of Object.entries(jsonData.composicoes)) {
      const custo = comp.custoUnitarioSP;
      
      if (!custo || custo <= 0) continue;

      const servicoAtualizado = {
        codigo: codigo,
        descricao: comp.descricao,
        unidade: comp.unidade,
        custoUnitario: custo,
        categoria: categoriasMap[comp.categoria] || comp.categoria || 'Geral',
        insumos: servicosSINAPI[codigo]?.insumos || gerarInsumosGenericos(comp, custo, jsonData.insumos || {})
      };

      if (servicosSINAPI[codigo]) {
        // Atualiza serviço existente (mantém insumos se já existirem)
        servicosSINAPI[codigo] = {
          ...servicosSINAPI[codigo],
          ...servicoAtualizado,
          insumos: servicosSINAPI[codigo].insumos // Mantém insumos detalhados
        };
        atualizados++;
      } else {
        // Adiciona novo serviço
        servicosSINAPI[codigo] = servicoAtualizado;
        novos++;
      }
    }

    // Atualizar categorias
    const novasCategorias = new Set(['Todas']);
    for (const servico of Object.values(servicosSINAPI)) {
      novasCategorias.add(servico.categoria);
    }
    
    categoriasSINAPI.length = 0;
    categoriasSINAPI.push(...Array.from(novasCategorias).sort());

    console.log(`✅ SINAPI atualizado: ${atualizados} serviços atualizados, ${novos} novos`);
    console.log(`📊 Total de serviços: ${Object.keys(servicosSINAPI).length}`);
    
    return true;
  } catch (error) {
    console.error('❌ Erro ao atualizar SINAPI:', error);
    return false;
  }
};

// Função auxiliar para gerar insumos genéricos quando necessário
function gerarInsumosGenericos(comp, custoTotal, insumosDisponiveis) {
  const insumos = [];
  
  // Percentual típico de mão de obra (35%)
  const percentualMO = 0.35;
  const custoMO = custoTotal * percentualMO;
  
  // Adicionar mão de obra genérica
  insumos.push({
    codigo: 'MO_GENERICA',
    descricao: 'Mão de obra',
    unidade: 'h',
    coeficiente: parseFloat((custoMO / 24.47).toFixed(2)),
    precoUnitario: 24.47
  });
  
  // Adicionar material genérico
  const custoMaterial = custoTotal - custoMO;
  insumos.push({
    codigo: 'MAT_GENERICO',
    descricao: 'Materiais diversos',
    unidade: comp.unidade || 'un',
    coeficiente: 1.0,
    precoUnitario: parseFloat(custoMaterial.toFixed(2))
  });
  
  return insumos;
}

// Função para forçar recarregamento do JSON (útil para debug)
export const forcarAtualizacaoSINAPI = async () => {
  dadosJSONCache = null;
  ultimaAtualizacaoJSON = null;
  return await atualizarDadosSINAPI();
};

